import re
t=open("ModelFiles/xml/Sco-GEM.xml").read()
ln=lambda p:t.count("\n",0,p)+1
for m in re.finditer(r'<species [^>]*>',t):
    s=m.group(0)
    if re.search(r'germicidin|flaviolin|nphtatt|M_3oiC6ACP|M_3oaiC7ACP|M_emcoa|M_mmcoa|M_malcoa_c"',s): print(ln(m.start()),re.search(r'id="([^"]+)"',s).group(1),re.search(r' name="([^"]*)"',s).group(1),re.search(r'compartment="(\w+)"',s).group(1))
print('--sinks/exchanges/DM')
for m in re.finditer(r'<reaction [^>]*>.*?</reaction>',t,re.S):
    b=m.group(0); hd=re.match(r'<reaction [^>]*>',b).group(0)
    rid=re.search(r' id="([^"]+)"',hd).group(1)
    if re.search(r'germicidin|flaviolin|nphtatt',b) and rid.startswith(('R_DM','R_SK','R_EX')): print(ln(m.start()),rid,re.findall(r'fbc:(?:lower|upper)FluxBound="([^"]+)"',hd))
print('--params')
for m in re.finditer(r'<parameter [^>]*>',t[:t.find('<listOfCompartments')+200000]): print(m.group(0)[:150])
E

